<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted} from 'vue';
import {invoke} from '@tauri-apps/api/core';
import Icon from './Icon.vue';
import AuthPanel from './AuthPanel';
import SyncPanel from './SyncPanel.vue';
import UpdatePanel from './UpdatePanel.vue';
import TaskBoard from './TaskBoard.vue';
import {leaves,taskNotice,taskProgress,taskSummary} from './tasks';
const taskEditing=ref(false);
import {type Order,type Entry,type Preferences,defaultPreferences,kinds,statuses,entryKinds,localDate,addDays,cents,decimal,money,balance,urgency as orderUrgency,blankOrder} from './model';
const preferences=ref<Preferences>({...defaultPreferences}),workspaceId=ref('');
const preferencesDraft=ref<Preferences>({...defaultPreferences});
const directoryDialog=ref(false),directoryMode=ref('relocate'),directoryTarget=ref('');
const exportDialog=ref(false),exportKind=ref('orders'),exportIncludeTrash=ref(false);
const dueManuallyEdited=ref(false),kindFilter=ref('all'),sortBy=ref('recent');
const editorBaseline=ref(''),discardDialog=ref(false);
const editorPage=ref(false);
function expandProject(){editorPage.value=true;editorTab.value='tasks'}
function editorFingerprint(){return JSON.stringify({order:editor.value,quote:quote.value})}
function urgency(order:Order){return orderUrgency(order,preferences.value.physicalReminderDays,preferences.value.digitalReminderDays)}
function progressText(order:Order){return order.tasks.length?taskSummary(order.tasks,order.status).progress:order.progress||'待补充进度'}
function nextText(order:Order){return order.tasks.length?taskSummary(order.tasks,order.status).next:order.nextStep||'待补充下一步'}
const native='__TAURI_INTERNALS__' in window;
const previewMode=ref(false);
const page=ref('overview'),ready=ref(false),initialized=ref(false),busy=ref(false),error=ref(''),notice=ref(''),dataDirectory=ref('');
const orders=ref<Order[]>([]),entries=ref<Entry[]>([]),query=ref(''),filter=ref('all');
const editor=ref<Order|null>(null),quote=ref('0.00'),editorTab=ref('basic'),history=ref<{action:string;at:string}[]>([]);
const payment=ref<{orderId:string;kind:string;amount:string;date:string;method:string;custom:string;note:string;id:string}|null>(null);
const remove=ref<Order|null>(null),voiding=ref<Entry|null>(null),voidReason=ref(''),copyText=ref<string|null>(null),cash=ref('');
const nav=[{id:'overview',label:'概览',icon:'overview'},{id:'orders',label:'工作项目',icon:'orders'},{id:'money',label:'收支利润',icon:'wallet'},{id:'shipping',label:'物流',icon:'shipping'},{id:'trash',label:'回收站',icon:'trash'},{id:'settings',label:'设置',icon:'settings'}];
const live=computed(()=>orders.value.filter(o=>!o.deletedAt));
const totals=computed(()=>live.value.reduce((s,o)=>{const b=balance(o,entries.value);s.received+=b.received;s.cost+=b.cost;s.profit+=b.profit;if(o.status!=='cancelled'){s.quote+=BigInt(o.quoteCents);s.remaining+=b.remaining;}return s},{quote:0n,received:0n,cost:0n,profit:0n,remaining:0n}));
const pending=computed(()=>live.value.filter(o=>!['done','cancelled'].includes(o.status)).sort((a,b)=>(a.dueDate||'9999').localeCompare(b.dueDate||'9999')));
const unpaid=computed(()=>live.value.filter(o=>o.status!=='cancelled'&&balance(o,entries.value).remaining>0n));
const activeCount=computed(()=>pending.value.length),doneCount=computed(()=>live.value.filter(o=>o.status==='done').length);
const taskAlerts=computed(()=>pending.value.flatMap(order=>leaves(order.tasks).filter(t=>t.status!=='done').map(task=>({order,task,notice:taskNotice(task,order.tasks)}))).filter(item=>['red','orange'].includes(item.notice.tone)).sort((a,b)=>(a.notice.date||'9999').localeCompare(b.notice.date||'9999')));
async function openTaskOrder(order:Order){await openOrder(order);expandProject()}
const shown=computed(()=>{
 let list=page.value==='trash'?orders.value.filter(o=>o.deletedAt):live.value;
 if(page.value==='shipping')list=list.filter(o=>o.kind==='physical');
 if(kindFilter.value!=='all')list=list.filter(o=>o.kind===kindFilter.value);
 const q=query.value.trim().toLocaleLowerCase();if(q)list=list.filter(o=>`${o.number} ${o.title} ${o.progress} ${o.nextStep} ${o.notes} ${o.trackingNumber} ${o.tasks.map(t=>`${t.title} ${t.notes} ${t.waitingReason}`).join(' ')}`.toLocaleLowerCase().includes(q));
 if(filter.value==='unpaid')list=list.filter(o=>balance(o,entries.value).remaining>0n&&o.status!=='cancelled');
 else if(filter.value==='urgent')list=list.filter(o=>['red','orange'].includes(urgency(o).tone));
 else if(filter.value!=='all')list=list.filter(o=>o.status===filter.value);
 return [...list].sort((a,b)=>sortBy.value==='due'?(a.dueDate||'9999').localeCompare(b.dueDate||'9999'):sortBy.value==='amount'?(BigInt(a.quoteCents)===BigInt(b.quoteCents)?0:BigInt(a.quoteCents)>BigInt(b.quoteCents)?-1:1):b.acceptedDate.localeCompare(a.acceptedDate));
});
const ledgerEntries=computed(()=>entries.value.filter(e=>live.value.some(o=>o.id===e.orderId)));
const editedBalance=computed(()=>editor.value?balance(editor.value,entries.value):null);
const editedEntries=computed(()=>entries.value.filter(e=>e.orderId===editor.value?.id));
const paymentOrder=computed(()=>orders.value.find(o=>o.id===payment.value?.orderId));
const paymentBefore=computed(()=>paymentOrder.value?balance(paymentOrder.value,entries.value):null);
const paymentAfter=computed(()=>{
 if(!paymentOrder.value||!payment.value)return null;
 try{const amount=cents(payment.value.amount);if(BigInt(amount)<=0n)return null;return balance(paymentOrder.value,[...entries.value,{...payment.value,amountCents:amount,date:payment.value.date||null,voidedAt:null,voidReason:null}]);}catch{return null;}
});
let noticeTimer:ReturnType<typeof setTimeout>|undefined,cashTimer:ReturnType<typeof setTimeout>|undefined;
function toast(text:string){notice.value=text;if(noticeTimer)clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>notice.value='',4000)}
function navigate(id:string){if(editorPage.value&&editor.value){closeEditor();if(editor.value)return;}page.value=id;query.value='';filter.value='all';kindFilter.value='all';error.value='';}
async function api(path:string,body?:unknown):Promise<any>{
 if(native)return invoke('desk_request',{path,body:body??null});
 const response=await fetch(path,{method:body?'POST':'GET',headers:{'X-Desk-Request':'1',...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});
 const value=await response.json();if(!response.ok)throw Error(value.error||'操作未完成');return value;
}
async function act(action:string,payload:unknown={}){return api('/api/v3/action',{action,payload,workspaceId:workspaceId.value||null})}
async function refresh(){const data=await api('/api/v3/snapshot');if(data.taskWorkflow!==1)throw Error('当前后台仍是旧版。请在旧窗口的设置中退出本机后台，关闭旧窗口，再打开新版程序；账本和登录会保留。');previewMode.value=!!data.previewMode;orders.value=data.orders.map((o:Order)=>({...o,tasks:o.tasks||[]}));entries.value=data.money;dataDirectory.value=data.dataDirectory;workspaceId.value=data.workspaceId;preferences.value={...defaultPreferences,...data.preferences};preferencesDraft.value={...preferences.value};}
async function bootstrap(){busy.value=true;error.value='';try{if(native)await invoke('start_service');const workspace=await api('/api/v3/workspace');dataDirectory.value=workspace.dataDirectory;initialized.value=workspace.initialized;if(workspace.error)throw Error(workspace.error);if(initialized.value)await refresh();ready.value=true;}catch(e){error.value=String(e);}finally{busy.value=false}}
async function initialize(){busy.value=true;error.value='';try{await act('create-workspace');initialized.value=true;await refresh();toast('本地工作空间已创建');}catch(e){error.value=String(e)}finally{busy.value=false}}
async function openOrder(order?:Order){editorPage.value=false;taskEditing.value=false;editor.value=order?JSON.parse(JSON.stringify(order)):{...blankOrder(),kind:preferences.value.defaultKind,dueDate:preferences.value.defaultKind==='physical'?null:addDays(localDate(),1)};quote.value=decimal(editor.value.quoteCents);editorTab.value='basic';dueManuallyEdited.value=!!order;history.value=[];editorBaseline.value=editorFingerprint();if(order)try{history.value=await api(`/api/v3/history/${order.id}`)}catch{}}
function additionalOrder(order:Order){taskEditing.value=false;const next=blankOrder();next.number=order.number;next.parentId=order.id;next.kind=order.kind;next.dueDate=next.kind==='physical'?null:next.dueDate;editor.value=next;dueManuallyEdited.value=false;quote.value='0.00';editorTab.value='basic';history.value=[];editorBaseline.value=editorFingerprint();}
function defaultDue(){if(editor.value?.revision===0&&!dueManuallyEdited.value){editor.value.dueDate=editor.value.kind==='physical'?null:addDays(editor.value.acceptedDate,1)}}
function closeEditor(){if(busy.value)return;if(editor.value&&(taskEditing.value||editorFingerprint()!==editorBaseline.value)){discardDialog.value=true;return;}editor.value=null;}
async function saveOrder(){if(!editor.value||busy.value)return;if(taskEditing.value){error.value='请先应用或取消正在编辑的任务';return;}busy.value=true;error.value='';try{
 const order=JSON.parse(JSON.stringify(editor.value));order.quoteCents=cents(quote.value);for(const key of ['dueDate','completedDate','shippedDate','deliveredDate','parentId'] as const)if(!order[key])order[key]=null;
 const saved=await act('save-order',order);await refresh();if(editorPage.value){editor.value=JSON.parse(JSON.stringify(orders.value.find(o=>o.id===saved.id)||saved));quote.value=decimal(editor.value!.quoteCents);editorBaseline.value=editorFingerprint();history.value=await api(`/api/v3/history/${saved.id}`);}else editor.value=null;toast(saved.revision===1?'订单已保存':'订单已更新');
 }catch(e){error.value=String(e)}finally{busy.value=false}}
async function quickDone(order:Order){if(leaves(order.tasks).some(t=>t.status!=='done')&&!window.confirm('还有未完成任务，仍将整笔订单标记为完成？任务记录会保留。'))return;busy.value=true;error.value='';try{await act('save-order',{...order,status:'done',completedDate:localDate()});await refresh();toast('已标记完成，收款和物流可继续跟进');}catch(e){error.value=String(e)}finally{busy.value=false}}
function newPayment(order:Order,kind='receipt'){const b=balance(order,entries.value);const preferred=localStorage.getItem(`desk-method-${kind}`)||(kind==='cost'?preferences.value.costMethod:preferences.value.receiptMethod);payment.value={id:crypto.randomUUID(),orderId:order.id,kind,amount:kind==='receipt'&&b.remaining>0n?decimal(b.remaining):'',date:preferences.value.entryDateToday?localDate():'',method:['微信','支付宝','银行卡','现金'].includes(preferred)?preferred:'其他',custom:['微信','支付宝','银行卡','现金','其他'].includes(preferred)?'':preferred,note:''};}
async function savePayment(){if(!payment.value||busy.value)return;busy.value=true;error.value='';try{
 const p=payment.value;const value=cents(p.amount);if(BigInt(value)<=0n)throw Error('请输入大于零的金额');const method=p.method==='其他'?p.custom.trim()||'其他':p.method;
 await act('add-money',{id:p.id,orderId:p.orderId,kind:p.kind,amountCents:value,date:p.date||null,method,note:p.note,voidedAt:null,voidReason:null});
 localStorage.setItem(`desk-method-${p.kind}`,method);await refresh();payment.value=null;
 if(p.kind==='receipt'&&preferences.value.moneyAnimation){cash.value=`+ ${money(value)}`;if(cashTimer)clearTimeout(cashTimer);cashTimer=setTimeout(()=>cash.value='',2200)}toast(`${entryKinds[p.kind]}已记录`);
 }catch(e){error.value=String(e)}finally{busy.value=false}}
async function trash(order:Order,restore=false){busy.value=true;error.value='';try{await act(restore?'restore-order':'trash-order',{id:order.id,revision:order.revision});await refresh();remove.value=null;editor.value=null;toast(restore?'项目已恢复':'项目已移入回收站，收支记录保留');}catch(e){error.value=String(e)}finally{busy.value=false}}
async function voidMoney(){if(!voiding.value)return;busy.value=true;error.value='';try{await act('void-money',{id:voiding.value.id,reason:voidReason.value});await refresh();voiding.value=null;voidReason.value='';toast('流水已作废，原记录仍可查看');}catch(e){error.value=String(e)}finally{busy.value=false}}
function buildCopy(){const amounts=new Map<string,bigint>();for(const o of unpaid.value){amounts.set(o.number,(amounts.get(o.number)||0n)+balance(o,entries.value).remaining)}copyText.value=[...amounts].map(([number,value])=>`${number} ${decimal(value)}元`).join('\n');}
async function copy(value:string){try{await navigator.clipboard.writeText(value);toast('已复制')}catch{error.value='剪贴板暂不可用，请选中文本手动复制';}}
async function backup(){busy.value=true;error.value='';try{const result=await act('backup');toast('完整本地备份已保存');backupPath.value=result.path;}catch(e){error.value=String(e)}finally{busy.value=false}}
async function openWeb(){try{await invoke('open_workbench_web')}catch(e){error.value=String(e)}}
async function openFolder(path:string){try{await invoke('open_project_folder',{path})}catch(e){error.value=String(e)}}
async function pickFolder(target:'directory'|'project'){try{const value=await invoke<string|null>('choose_folder');if(value){if(target==='directory')directoryTarget.value=value;else if(editor.value)editor.value.projectPath=value;}}catch(e){error.value=String(e)}}
async function savePreferences(){busy.value=true;error.value='';try{await act('save-preferences',preferencesDraft.value);await refresh();for(const kind of ['receipt','cost'])localStorage.removeItem(`desk-method-${kind}`);toast('提醒和填写偏好已保存');}catch(e){error.value=String(e)}finally{busy.value=false}}
function showDirectory(mode:string){directoryMode.value=mode;directoryTarget.value='';directoryDialog.value=true;}
async function changeDirectory(){busy.value=true;error.value='';try{await act('change-directory',{mode:directoryMode.value,directory:directoryTarget.value.trim()});await refresh();initialized.value=true;ready.value=true;editor.value=null;payment.value=null;directoryDialog.value=false;backupPath.value='';showBackups.value=false;toast('数据目录已更新，原有目录仍保留');}catch(e){error.value=String(e)}finally{busy.value=false}}
async function exportData(){busy.value=true;error.value='';try{
 const source=exportIncludeTrash.value?orders.value:live.value;let rows:string[][]=[];
 if(exportKind.value==='orders'){rows=[['订单编号','项目名称','交付类型','工作状态','接单日期','截止日期','完成日期','订单金额(元)','净收款(元)','实际支出(元)','实际利润(元)','待收款(元)','当前进度','下一步','工程路径','备注','快递公司','快递单号','寄出日期','收货日期','已删除','补充进度说明','其他待办说明']];for(const o of source){const b=balance(o,entries.value);rows.push([o.number,o.title,kinds[o.kind],statuses[o.status],o.acceptedDate,o.dueDate||'',o.completedDate||'',decimal(o.quoteCents),decimal(b.received),decimal(b.cost),decimal(b.profit),decimal(b.remaining),progressText(o),nextText(o),o.projectPath,o.notes,o.carrier,o.trackingNumber,o.shippedDate||'',o.deliveredDate||'',o.deletedAt?'是':'否',o.tasks.length?o.progress:'',o.tasks.length?o.nextStep:'']);}}
 else if(exportKind.value==='money'){rows=[['订单编号','项目名称','类型','金额(元)','日期','方式','备注','已作废','作废原因']];for(const e of entries.value.filter(e=>source.some(o=>o.id===e.orderId))){rows.push([orderNumber(e.orderId),orderName(e.orderId),entryKinds[e.kind],decimal(e.amountCents),e.date||'',e.method,e.note,e.voidedAt?'是':'否',e.voidReason||'']);}}
 else if(exportKind.value==='tasks'){rows=[['订单编号','项目名称','父任务','任务名称','状态','计划开始','截止日期','跟进日期','提前提醒(天)','创建时间','实际开始','实际完成','前置任务','等待原因','进度备注']];for(const o of source)for(const t of o.tasks)rows.push([o.number,o.title,o.tasks.find(p=>p.id===t.parentId)?.title||'',t.title,({todo:'未开始',doing:'进行中',waiting:'等待中',done:'已完成',cancelled:'已取消'} as Record<string,string>)[t.status]||t.status,t.plannedStart||'',t.dueDate||'',t.followUpDate||'',String(t.reminderDays),t.createdAt,t.startedAt||'',t.completedAt||'',o.tasks.find(p=>p.id===t.dependsOn)?.title||'',t.waitingReason,t.notes]);}
 else{rows=[['订单编号','项目名称','待收款(元)']];for(const o of source.filter(o=>o.status!=='cancelled'&&balance(o,entries.value).remaining>0n))rows.push([o.number,o.title,decimal(balance(o,entries.value).remaining)]);}
 const numeric=new Set(exportKind.value==='orders'?[7,8,9,10,11]:exportKind.value==='money'?[3]:[2]);const cell=(value:string,isAmount:boolean)=>'"'+(/^[\s]*[=+@-]/.test(value)&&!(isAmount&&/^-?\d{1,12}\.\d{2}$/.test(value))?"'"+value:value).replaceAll('"','""')+'"';
 const content='\uFEFF'+rows.map((row,index)=>row.map((value,column)=>cell(value,index>0&&numeric.has(column))).join(',')).join('\r\n');const name=`接单工作台-${exportKind.value==='orders'?'订单':exportKind.value==='money'?'收支流水':exportKind.value==='tasks'?'任务流程':'未结款'}-${localDate()}.csv`;
 if(native){const path=await invoke<string|null>('save_export',{name,content});if(!path)return;toast('表格已导出');}
 else{const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('表格已生成');}exportDialog.value=false;
 }catch(e){error.value=String(e)}finally{busy.value=false}}
function setDueAfter(days:number){if(editor.value){editor.value.dueDate=addDays(editor.value.acceptedDate||localDate(),days);dueManuallyEdited.value=true;}}
const backupPath=ref(''),backupList=ref<{name:string;bytes:number}[]>([]),showBackups=ref(false),restoreName=ref<string|null>(null);
async function loadBackups(){busy.value=true;error.value='';try{backupList.value=await api('/api/v3/backups');showBackups.value=true;}catch(e){error.value=String(e)}finally{busy.value=false}}
async function restoreBackup(){if(!restoreName.value)return;busy.value=true;error.value='';try{const result=await act('restore-backup',{name:restoreName.value});backupPath.value=result.protectionBackup;await refresh();restoreName.value=null;showBackups.value=false;toast('已恢复所选版本，恢复前的数据已另存保护备份');}catch(e){error.value=String(e)}finally{busy.value=false}}
function orderName(id:string){return orders.value.find(o=>o.id===id)?.title||'未知项目'}
function orderNumber(id:string){return orders.value.find(o=>o.id===id)?.number||'—'}
function entrySign(e:Entry){return ['receipt','cost-refund'].includes(e.kind)?'+':'−'}
const historyLabels:Record<string,string>={'save-order':'保存项目','add-money':'记录收支','void-money':'作废流水','trash-order':'移入回收站','restore-order':'恢复项目'};
function onKey(event:KeyboardEvent){if(event.key==='Escape'&&!busy.value){if(discardDialog.value)discardDialog.value=false;else if(directoryDialog.value)directoryDialog.value=false;else if(exportDialog.value)exportDialog.value=false;else if(restoreName.value)restoreName.value=null;else if(voiding.value)voiding.value=null;else if(payment.value)payment.value=null;else if(copyText.value!==null)copyText.value=null;else if(remove.value)remove.value=null;else closeEditor();}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'&&editor.value&&!payment.value){event.preventDefault();void saveOrder();}}
onMounted(()=>{void bootstrap();window.addEventListener('keydown',onKey)});onUnmounted(()=>{window.removeEventListener('keydown',onKey);if(noticeTimer)clearTimeout(noticeTimer);if(cashTimer)clearTimeout(cashTimer)});
</script>

<template>
 <div class="app-shell" :class="{'project-view-open':editor&&editorPage}">
  <aside class="sidebar">
   <a class="brand" href="#" @click.prevent="navigate('overview')"><span class="brand-mark"><Icon name="orders"/></span><span>接单工作台<small>让每一单都有着落</small></span></a>
   <nav aria-label="主导航"><button v-for="item in nav" :key="item.id" :class="{active:page===item.id}" @click="navigate(item.id)"><Icon :name="item.icon"/><span>{{item.label}}</span><b v-if="item.id==='orders'&&activeCount">{{activeCount}}</b></button></nav>
   <div class="sidebar-foot"><span class="local-dot"/>本机保存 · 离线可用<small>新版独立工作空间<br>远端手动同步 · 本地离线可用</small></div>
  </aside>
  <main v-show="!(editor&&editorPage)" class="workspace">
   <div v-if="previewMode" class="preview-banner">界面预览 · 当前为演示数据，与正式账本隔离</div><header class="page-header"><div><div class="eyebrow">{{localDate()}} · 个人接单工作台</div><h1>{{nav.find(n=>n.id===page)?.label}}</h1><p>{{page==='overview'?'看清手上的事，也看清每一笔收益。':page==='orders'?'按编号管理项目，工作、收款和物流分别跟进。':page==='money'?'到账是收入，减去支出才是利润。':page==='shipping'?'实物订单的寄出、签收和快递信息。':page==='trash'?'误删可以恢复，相关收支记录完整保留。':'本地数据、备份和账户连接。'}}</p></div><div class="header-actions"><button class="icon-button" :disabled="busy" @click="bootstrap" aria-label="刷新">↻</button><button v-if="initialized" class="export-top" @click="exportDialog=true">导出表格</button><button v-if="initialized&&page!=='trash'" class="primary" @click="openOrder()"><Icon name="plus"/>新增订单</button></div></header>
   <div v-if="error" class="error-banner" role="alert"><span>{{error}}</span><button @click="error=''" aria-label="关闭提示"><Icon name="close"/></button></div>
   <div v-if="!ready" class="empty card"><h2>{{busy?'正在连接本机后台…':'暂未连接本机后台'}}</h2><p>连接尚未完成。点击重新连接后会读取原来的账本，无需重新创建。</p><button :disabled="busy" @click="bootstrap">重新连接</button><button :disabled="busy" @click="showDirectory('open')">选择已有账本目录</button></div>
   <div v-else-if="!initialized" class="welcome card"><span class="large-icon"><Icon name="orders"/></span><h2>开始整理你的接单工作</h2><p>建立一份独立的本地账本。已有旧版订单保持原样，之后统一迁移。</p><div class="directory">{{dataDirectory}}</div><button class="primary" :disabled="busy" @click="initialize">创建本地工作空间</button><div class="welcome-options"><button @click="showDirectory('create')">选择其他目录创建</button><button @click="showDirectory('open')">打开已有账本</button></div></div>
   <template v-else>
    <template v-if="page==='overview'">

     <div class="overview-summary">
      <section class="card summary-work" aria-label="订单情况">
       <div class="summary-label"><Icon name="orders"/><span>订单情况</span></div>
       <div class="stat"><span>全部订单</span><strong>{{live.length}}<small>单</small></strong><footer><span>{{activeCount}} 进行中</span><i/>{{doneCount}} 已完成</footer></div>
      </section>
      <section class="card summary-finance" aria-label="收支情况">
       <div class="summary-label"><Icon name="wallet"/><span>收支情况</span><small>订单总额 {{money(totals.quote)}}</small></div>
       <div class="summary-finance-values">
        <div class="stat green"><span>净收款</span><strong>{{money(totals.received)}}</strong><footer>已到账，扣除退款</footer></div>
        <div class="stat" :class="totals.profit>=0n?'green':'red'"><span>实际利润</span><strong>{{money(totals.profit)}}</strong><footer>实际支出 {{money(totals.cost)}}</footer></div>
        <button class="stat red summary-receivable" @click="navigate('money');filter='unpaid'"><span>待收款</span><strong>{{money(totals.remaining)}}</strong><footer>{{unpaid.length}} 个项目 <Icon name="arrow"/></footer></button>
       </div>
      </section>
     </div>
     <section v-if="taskAlerts.length" class="card task-alert-panel"><div class="section-heading"><div><h2>任务提醒 <span class="panel-count">{{taskAlerts.length}}</span></h2><p>即将截止、逾期或需要跟进的子任务</p></div></div><button v-for="item in taskAlerts.slice(0,5)" :key="item.task.id" class="task-alert-row" @click="openTaskOrder(item.order)"><span><small>{{item.order.number}} · {{item.order.title}}</small><strong>{{item.task.title}}</strong><small v-if="item.task.status==='waiting'">{{item.task.waitingReason||'等待跟进'}}</small></span><span class="badge" :class="item.notice.tone">{{item.notice.text}}</span><Icon name="arrow"/></button><p v-if="taskAlerts.length>5" class="hint">其余提醒可在对应订单的“任务与流程”查看。</p></section><div class="overview-columns">
      <section class="card overview-work">
       <div class="section-heading"><div class="panel-title"><span class="panel-icon"><Icon name="orders"/></span><div><h2>工作待办 <span class="panel-count">{{pending.length}}</span></h2><p>优先显示截止最近的 3 项</p></div></div><button class="text-button" @click="navigate('orders')">全部项目 <Icon name="arrow"/></button></div>
       <div v-if="!pending.length" class="empty overview-empty"><span class="success-icon"><Icon :name="live.length?'check':'orders'"/></span><h3>{{live.length?'暂无进行中的工作':'还没有订单'}}</h3><p>{{live.length?'已完成和已取消的项目可在工作项目中查看。':'先新增一单，记录进度、截止日期和收益。'}}</p><button v-if="!live.length" class="primary" @click="openOrder()"><Icon name="plus"/>新增第一单</button></div>
       <div v-for="o in pending.slice(0,3)" :key="o.id" class="task-row">
        <button class="task-title" @click="openOrder(o)"><small class="order-number">{{o.number}}</small><strong>{{o.title}}</strong><span>{{o.tasks.length?nextText(o):(o.nextStep||o.progress||'待补充下一步')}}</span></button>
        <span class="badge" :class="urgency(o).tone">{{urgency(o).text}}</span><button class="icon-button" :disabled="busy" @click="quickDone(o)" title="标记完成"><Icon name="check"/></button>
       </div>
       <button v-if="pending.length>3" class="overview-more" @click="navigate('orders')">还有 {{pending.length-3}} 项待办，查看全部 <Icon name="arrow"/></button>
      </section>
      <section class="card overview-collection">
       <div class="section-heading"><div class="panel-title"><span class="panel-icon"><Icon name="wallet"/></span><div><h2>收款跟进 <span class="panel-count">{{unpaid.length}}</span></h2><p>按编号核对，收一笔记一笔</p></div></div><button class="text-button" :disabled="!unpaid.length" @click="buildCopy"><Icon name="copy"/>复制清单</button></div>
       <div v-if="!unpaid.length" class="empty overview-empty"><h3>{{live.length?'暂无待收款':'还没有收款记录'}}</h3><p>{{live.length?'目前没有需要跟进的尾款。':'新增订单后，可以分次记收款和支出。'}}</p></div>
       <div v-for="o in unpaid.slice(0,3)" :key="o.id" class="task-row">
        <button class="task-title" @click="openOrder(o)"><small class="order-number">{{o.number}}</small><strong>{{o.title}}</strong></button><strong class="red nowrap">{{money(balance(o,entries).remaining)}}</strong><button class="small-button" @click="newPayment(o)">收款</button>
       </div>
       <button v-if="unpaid.length>3" class="overview-more" @click="navigate('money');filter='unpaid'">还有 {{unpaid.length-3}} 项待收款，查看全部 <Icon name="arrow"/></button>
      </section>
     </div>
    </template>
    <template v-if="['orders','shipping','trash'].includes(page)">
     <div class="toolbar card"><label class="search"><Icon name="search"/><input v-model="query" placeholder="搜索编号、名称、进度或快递单号" aria-label="搜索项目"/></label><select v-model="filter" aria-label="筛选状态"><option value="all">全部状态</option><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option><option value="unpaid">待收款</option><option value="urgent">需要关注</option></select><select v-if="page!=='shipping'" v-model="kindFilter" aria-label="交付类型"><option value="all">全部交付类型</option><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select><select v-model="sortBy" aria-label="排序"><option value="recent">接单日期由近到远</option><option value="due">截止日期由近到远</option><option value="amount">订单金额由高到低</option></select><span class="muted">共 {{shown.length}} 项</span></div>
     <div v-if="!shown.length" class="empty card"><h2>{{query?'没有匹配的项目':page==='trash'?'回收站是空的':page==='shipping'?'还没有实物项目':'还没有项目'}}</h2><p>{{query?'试试其他编号或名称。':'新增一单，开始记录进度与收益。'}}</p><button v-if="page==='orders'" class="primary" @click="openOrder()">新增订单</button></div>
     <div v-else class="card table-wrap"><table><thead><tr><th>订单编号</th><th>项目</th><th v-if="page!=='shipping'">状态 / 截止</th><th v-if="page==='orders'">当前进度 / 下一步</th><th v-if="page!=='shipping'">收款</th><template v-if="page==='shipping'"><th>物流状态</th><th>快递 / 单号</th><th>寄出 / 收货</th></template><th>操作</th></tr></thead><tbody><tr v-for="o in shown" :key="o.id"><td class="order-number">{{o.number}}</td><td><button class="project-link" @click="openOrder(o)">{{o.title}}</button><small>{{kinds[o.kind]}}<span v-if="o.parentId"> · 追加单</span></small></td><td v-if="page!=='shipping'"><span class="badge" :class="o.status==='done'?'green':o.status==='cancelled'?'muted':'blue'">{{statuses[o.status]}}</span><small :class="urgency(o).tone">{{o.dueDate||'未设截止'}} · {{urgency(o).text}}</small></td><td v-if="page==='orders'"><span>{{progressText(o)}}</span><small v-if="o.tasks.length">{{taskProgress(o.tasks)}}</small><small>下一步：{{nextText(o)}}</small></td><td v-if="page!=='shipping'"><strong :class="balance(o,entries).remaining>0n?'red':'green'">{{balance(o,entries).remaining>0n?`待收 ${money(balance(o,entries).remaining)}`:'已收齐'}}</strong><small :class="balance(o,entries).received>0n?'green':''">已收 {{money(balance(o,entries).received)}}</small></td><template v-if="page==='shipping'"><td><span class="badge" :class="o.deliveredDate?'green':o.shippedDate?'blue':'orange'">{{o.deliveredDate?'已签收':o.shippedDate?'已寄出':'待寄出'}}</span></td><td>{{o.carrier||'—'}}<small class="order-number">{{o.trackingNumber||'单号待补充'}}</small><button v-if="o.trackingNumber" class="text-button" @click="copy(o.trackingNumber)">复制单号</button></td><td>{{o.shippedDate||'未寄出'}}<small>收货：{{o.deliveredDate||'未签收'}}</small></td></template><td><div class="row-actions"><template v-if="page==='trash'"><button class="small-button" :disabled="busy" @click="trash(o,true)">恢复</button></template><template v-else><button class="small-button" @click="openOrder(o)">打开</button><button v-if="page==='orders'&&balance(o,entries).remaining>0n&&o.status!=='cancelled'" class="text-button green" @click="newPayment(o)">收款</button></template></div></td></tr></tbody></table></div>
    </template>
    <template v-if="page==='money'">
     <div class="stat-grid money-stats"><div class="stat card green"><span>净收款</span><strong>{{money(totals.received)}}</strong></div><div class="stat card"><span>实际支出</span><strong>{{money(totals.cost)}}</strong></div><div class="stat card" :class="totals.profit>=0n?'green':'red'"><span>实际利润</span><strong>{{money(totals.profit)}}</strong></div><div class="stat card red"><span>待收款</span><strong>{{money(totals.remaining)}}</strong></div></div>
     <section class="card"><div class="section-heading"><div><h2>按编号收支</h2><p>同编号的追加单分别记账，复制清单时按编号合计。</p></div><button class="primary" :disabled="!unpaid.length" @click="buildCopy"><Icon name="copy"/>复制未结款</button></div><div class="toolbar inset"><label class="search"><Icon name="search"/><input v-model="query" placeholder="搜索编号或项目"/></label><select v-model="filter"><option value="all">全部项目</option><option value="unpaid">仅待收款</option></select></div><div class="table-wrap"><table><thead><tr><th>订单编号</th><th>项目</th><th>订单金额</th><th>净收款</th><th>实际支出</th><th>实际利润</th><th>待收款</th><th>记录</th></tr></thead><tbody><tr v-for="o in shown" :key="o.id"><td class="order-number">{{o.number}}</td><td><button class="project-link" @click="openOrder(o)">{{o.title}}</button></td><td>{{money(o.quoteCents)}}</td><td class="green">{{money(balance(o,entries).received)}}</td><td>{{money(balance(o,entries).cost)}}</td><td :class="balance(o,entries).profit>=0n?'green':'red'"><strong>{{money(balance(o,entries).profit)}}</strong></td><td :class="balance(o,entries).remaining>0n?'red':'muted'">{{money(balance(o,entries).remaining)}}</td><td><div class="row-actions"><button class="small-button" @click="newPayment(o)">收款</button><button class="text-button" @click="newPayment(o,'cost')">支出</button></div></td></tr><tr v-if="!shown.length"><td colspan="8" class="empty">暂无项目</td></tr></tbody></table></div></section>
     <section class="card"><div class="section-heading"><div><h2>最近收支流水</h2><p>记录有误可以作废，原记录保留备查。</p></div></div><div class="table-wrap"><table><thead><tr><th>编号 / 项目</th><th>类型</th><th>金额</th><th>日期</th><th>方式</th><th>备注</th><th>操作</th></tr></thead><tbody><tr v-for="e in ledgerEntries.slice(0,60)" :key="e.id" :class="{voided:e.voidedAt}"><td class="order-number">{{orderNumber(e.orderId)}}<small>{{orderName(e.orderId)}}</small></td><td>{{entryKinds[e.kind]}}<small v-if="e.voidedAt">已作废</small></td><td :class="['receipt','cost-refund'].includes(e.kind)?'green':''">{{entrySign(e)}}{{money(e.amountCents)}}</td><td>{{e.date||'日期未记'}}</td><td>{{e.method||'—'}}</td><td>{{e.voidReason||e.note||'—'}}</td><td><button v-if="!e.voidedAt" class="text-button" @click="voiding=e;voidReason=''">作废</button></td></tr><tr v-if="!ledgerEntries.length"><td colspan="7" class="empty">还没有收支记录</td></tr></tbody></table></div></section>
    </template>
    <template v-if="page==='settings'"><section class="card"><div class="section-heading"><div><h2>本地工作空间</h2><p>账本保存在本机，可按目录切换不同工作台。程序更新不会重建或清空账本。</p></div></div><div class="settings-content"><label>数据目录</label><div class="directory">{{dataDirectory}}</div><p>账本、流水、项目历史一起备份。备份保存在当前目录的 backups 文件夹。</p><div class="row-actions"><button class="primary" :disabled="busy" @click="backup">立即备份</button><button @click="exportDialog=true">导出表格</button><button :disabled="busy" @click="loadBackups">查看备份与恢复</button><button v-if="native" @click="openWeb">在浏览器中打开</button><button :disabled="busy" @click="showDirectory('relocate')">迁移数据目录</button><button :disabled="busy" @click="showDirectory('open')">打开其他账本</button></div><p v-if="backupPath" class="directory">{{backupPath}}</p><div v-if="showBackups" class="backup-list"><p v-if="!backupList.length">还没有可恢复的备份，先点击立即备份。</p><div v-for="item in backupList" :key="item.name" class="history-row"><span class="backup-name">{{item.name}}<small>{{(item.bytes/1024).toFixed(1)}} KB</small></span><button class="small-button" :disabled="busy" @click="restoreName=item.name">恢复此版本</button></div></div><p class="muted">本地记录先保存；仅在下方远端同步区操作后才会加密上传。其他设备可导入恢复密钥连接同一账本。</p></div></section><section class="card"><div class="section-heading"><div><h2>提醒与填写偏好</h2><p>一次设置，后续新增和记账直接沿用。</p></div></div><form class="settings-content form-grid" @submit.prevent="savePreferences"><label>实物提前提醒（天）<input v-model.number="preferencesDraft.physicalReminderDays" type="number" min="0" max="90" required/></label><label>其他类型提前提醒（天）<input v-model.number="preferencesDraft.digitalReminderDays" type="number" min="0" max="90" required/></label><label>默认交付类型<select v-model="preferencesDraft.defaultKind"><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></label><label>默认收款方式<input v-model="preferencesDraft.receiptMethod" list="payment-methods" maxlength="30"/></label><label>默认支出方式<input v-model="preferencesDraft.costMethod" list="payment-methods" maxlength="30"/></label><datalist id="payment-methods"><option>微信</option><option>支付宝</option><option>银行卡</option><option>现金</option></datalist><div class="full preference-toggles"><label class="check-label"><input v-model="preferencesDraft.entryDateToday" type="checkbox"/>新记账时日期默认今天（仍可清空）</label><label class="check-label"><input v-model="preferencesDraft.moneyAnimation" type="checkbox"/>收款成功显示加钱动效</label></div><div class="full"><button class="primary" type="submit" :disabled="busy">保存偏好设置</button></div></form></section><SyncPanel :key="workspaceId" :action="act" :reload="refresh" :preview="previewMode"/><AuthPanel/><UpdatePanel/></template>
   </template>
  </main>
 <div v-if="editor" :class="editorPage?'project-page-layer':'modal-layer'" @mousedown.self="!editorPage&&closeEditor()"><section class="dialog order-dialog" :class="{'project-page':editorPage}" :role="editorPage?'region':'dialog'" :aria-modal="editorPage?undefined:true" :aria-label="editor.revision?'项目详情':'新增订单'"><header class="dialog-head"><div class="project-page-title"><button v-if="editorPage" type="button" class="text-button project-back" :disabled="busy" @click="closeEditor">← 返回{{nav.find(n=>n.id===page)?.label}}</button><small>{{editor.revision?editor.number:'记录下一笔工作'}}</small><h2>{{editorPage?(editor.title||'新增项目'):(editor.revision?'项目详情':'新增订单')}}</h2><p v-if="editorPage">{{kinds[editor.kind]}} · {{statuses[editor.status]}} · 截止 {{editor.dueDate||'待补充'}}<span v-if="editor.tasks.length"> · {{taskProgress(editor.tasks)}}</span></p></div><div class="row-actions"><button v-if="!editorPage" type="button" class="primary" @click="expandProject">进入项目详情页 <Icon name="arrow"/></button><button class="icon-button" :disabled="busy" @click="closeEditor" :aria-label="editorPage?'返回列表':'关闭'"><Icon name="close"/></button></div></header>
  <div v-if="error" class="error-banner" role="alert">{{error}}</div>
  <div v-if="editor.revision" class="detail-summary"><div><small>已收款</small><strong class="green">{{money(editedBalance!.received)}}</strong></div><div><small>实际利润</small><strong :class="editedBalance!.profit>=0n?'green':'red'">{{money(editedBalance!.profit)}}</strong></div><div><small>待收款</small><strong class="red">{{money(editedBalance!.remaining)}}</strong></div><div v-if="!editor.deletedAt" class="row-actions"><button class="small-button" @click="newPayment(editor)">收款</button><button class="text-button" @click="newPayment(editor,'cost')">支出</button></div></div>
  <div class="tabs"><button type="button" :class="{selected:editorTab==='tasks'}" @click="editorTab='tasks'">任务与流程</button><button :class="{selected:editorTab==='basic'}" @click="editorTab='basic'">{{editor.tasks.length?'基本信息':'基本与进度'}}</button><button v-if="editor.kind==='physical'" :class="{selected:editorTab==='shipping'}" @click="editorTab='shipping'">物流</button><button v-if="editor.revision" :class="{selected:editorTab==='records'}" @click="editorTab='records'">收支与历史</button></div>
  <form @submit.prevent="saveOrder"><div class="dialog-body"><TaskBoard v-show="editorTab==='tasks'" v-model="editor.tasks" :kind="editor.kind" :order-due="editor.dueDate" :order-status="editor.status" @complete="editor.status='done';editor.completedDate ||=localDate()" :disabled="busy||!!editor.deletedAt" @editing="taskEditing=$event"/><div v-show="editorTab==='basic'" class="form-grid"><label>订单编号 <em>*</em><input v-model="editor.number" required maxlength="80" placeholder="例如 LYK-1112-005"/></label><label>项目名称 <em>*</em><input v-model="editor.title" required maxlength="200" placeholder="例如 51 单片机流水灯仿真"/></label><label>交付类型<select v-model="editor.kind" @change="defaultDue"><option v-for="(label,key) in kinds" :key="key" :value="key">{{label}}</option></select></label><label>工作状态<select v-model="editor.status"><option v-for="(label,key) in statuses" :key="key" :value="key">{{label}}</option></select></label><label>接单日期<input v-model="editor.acceptedDate" type="date" required @change="defaultDue"/></label><label>截止日期<input v-model="editor.dueDate" type="date" @change="dueManuallyEdited=true"/><div class="date-shortcuts"><button type="button" @click="setDueAfter(1)">接单后1天</button><button type="button" @click="setDueAfter(3)">3天</button><button type="button" @click="setDueAfter(7)">7天</button></div><small>{{editor.kind==='physical'?'实物提前 '+preferences.physicalReminderDays+' 天提醒，请填写实际截止日期':'未填写时默认为接单后一天，提前 '+preferences.digitalReminderDays+' 天提醒'}}</small></label><label>订单金额（元）<input v-model="quote" inputmode="decimal" placeholder="0.00" required/></label><label v-if="editor.status==='done'">完成日期<input v-model="editor.completedDate" type="date"/><small>{{editor.historicalDates?'历史记录：留空表示完成日期未知':'不填则记为今天'}}</small></label><div v-if="editor.tasks.length" class="full automatic-progress"><div><span class="badge blue">由任务自动汇总</span><button type="button" class="text-button" @click="editorTab='tasks'">管理任务 →</button></div><p><strong>当前进度</strong>{{progressText(editor)}}</p><p><strong>下一步</strong>{{nextText(editor)}}</p><small>不需要重复填写。原来的文字保留在下方作为补充，不会覆盖任务状态。</small></div><label class="full">{{editor.tasks.length?'补充进度说明（可选）':'当前做到哪里'}}<input v-model="editor.progress" placeholder="例如：代码已完成，等待调试串口"/></label><label class="full">{{editor.tasks.length?'其他待办 / 沟通说明（可选）':'下一步做什么'}}<input v-model="editor.nextStep" placeholder="例如：连上硬件测试，再发演示视频"/></label><label class="full">工程路径<div class="input-with-action"><input v-model="editor.projectPath" placeholder="例如 D:\projects\项目名称"/><button v-if="native" type="button" @click="pickFolder('project')">选择文件夹</button></div><div v-if="editor.projectPath" class="row-actions"><button v-if="native" type="button" class="text-button" @click="openFolder(editor.projectPath)">打开工程文件夹</button><button type="button" class="text-button" @click="copy(editor.projectPath)">复制路径</button></div></label><label class="full">关联原单（追加项目可选）<select v-model="editor.parentId"><option :value="null">不关联</option><option v-for="o in live.filter(o=>o.id!==editor!.id)" :key="o.id" :value="o.id">{{o.number}} · {{o.title}}</option></select></label><label class="full">备注<textarea v-model="editor.notes" rows="3" placeholder="交付要求、客户反馈、待确认事项…"/></label></div>
  <div v-show="editorTab==='shipping'" class="form-grid"><label>快递公司<input v-model="editor.carrier" list="carriers" placeholder="选择或直接输入"/><datalist id="carriers"><option>顺丰</option><option>中通</option><option>圆通</option><option>申通</option><option>韵达</option><option>京东</option><option>邮政</option></datalist></label><label>快递单号<input v-model="editor.trackingNumber" placeholder="寄出后补充"/></label><label>寄出日期<input v-model="editor.shippedDate" type="date"/></label><label>收货日期<input v-model="editor.deliveredDate" type="date"/></label><p class="full muted">工作完成、收款和物流分开记录。完成制作后仍可继续登记寄出和签收。</p></div>
  <div v-if="editorTab==='records'"><h3>收支记录</h3><div v-for="e in editedEntries" :key="e.id" class="history-row" :class="{voided:e.voidedAt}"><span>{{entryKinds[e.kind]}} · {{e.method||'未记方式'}}<small>{{e.date||'日期未记'}} {{e.voidedAt?'· 已作废':''}}</small></span><strong :class="['receipt','cost-refund'].includes(e.kind)?'green':''">{{entrySign(e)}}{{money(e.amountCents)}}</strong></div><p v-if="!editedEntries.length" class="muted">还没有收支记录</p><h3>项目历史</h3><div v-for="(item,i) in history" :key="i" class="history-row"><span>{{historyLabels[item.action]||item.action}}</span><small>{{new Date(item.at).toLocaleString('zh-CN')}}</small></div></div></div>
  <footer class="dialog-footer"><button v-if="editor.revision&&!editor.deletedAt" type="button" class="text-button danger" @click="remove=editor"><Icon name="trash"/>移入回收站</button><button v-if="editor.revision&&!editor.deletedAt" type="button" class="text-button" @click="additionalOrder(editor)">追加一单</button><span class="spacer"/><button type="button" :disabled="busy" @click="closeEditor">取消</button><button class="primary" type="submit" :disabled="busy||!!editor.deletedAt||taskEditing">{{busy?'保存中…':'保存项目'}}</button></footer></form></section></div>


 </div>
 <Transition name="toast"><div v-if="notice" class="toast" role="status"><Icon name="check"/>{{notice}}</div></Transition>
 <Transition name="cash"><div v-if="cash" class="cash-animation">{{cash}}<small>收款成功</small></div></Transition>

 <div v-if="payment" class="modal-layer upper" @mousedown.self="!busy&&(payment=null)"><section class="dialog compact" role="dialog" aria-modal="true" :aria-label="entryKinds[payment.kind]"><header class="dialog-head"><div><small class="order-number">{{orderNumber(payment.orderId)}}</small><h2>{{entryKinds[payment.kind]}}</h2><p>{{orderName(payment.orderId)}}</p></div><button class="icon-button" :disabled="busy" @click="payment=null"><Icon name="close"/></button></header><form @submit.prevent="savePayment"><div class="dialog-body form-grid"><div v-if="error" class="error-banner full">{{error}}</div><div v-if="paymentBefore" class="full payment-context"><span>订单金额 <strong>{{money(paymentOrder!.quoteCents)}}</strong></span><span>已收 <strong class="green">{{money(paymentBefore.received)}}</strong></span><span>待收 <strong :class="paymentBefore.remaining>0n?'red':'muted'">{{money(paymentBefore.remaining)}}</strong></span></div><label class="full">类型<select v-model="payment.kind"><option v-for="(label,key) in entryKinds" :key="key" :value="key">{{label}}</option></select></label><label class="full">金额（元）<input v-model="payment.amount" class="amount-input" inputmode="decimal" required autofocus placeholder="0.00"/><button v-if="payment.kind==='receipt'&&paymentBefore&&paymentBefore.remaining>0n" type="button" class="text-button" @click="payment.amount=decimal(paymentBefore.remaining)">填入剩余待收 {{money(paymentBefore.remaining)}}</button></label><div v-if="paymentAfter" class="full payment-preview"><strong>本次保存后</strong><div><span>净收款 <b class="green">{{money(paymentAfter.received)}}</b></span><span>实际利润 <b :class="paymentAfter.profit>=0n?'green':'red'">{{money(paymentAfter.profit)}}</b></span><span>待收 <b :class="paymentAfter.remaining>0n?'red':'green'">{{money(paymentAfter.remaining)}}</b></span></div><p v-if="paymentAfter.overpaid>0n" class="orange">累计收款超过订单金额 {{money(paymentAfter.overpaid)}}，请核对金额或订单报价。</p><p v-if="paymentAfter.received<0n||paymentAfter.cost<0n" class="red">退款或支出退回超过已记录金额，请核对。</p></div><label>方式<select v-model="payment.method"><option>微信</option><option>支付宝</option><option>银行卡</option><option>现金</option><option>其他</option></select></label><label>日期（可不填）<input v-model="payment.date" type="date"/><div class="date-shortcuts"><button type="button" @click="payment.date=localDate()">今天</button><button type="button" @click="payment.date=''">日期未知</button></div></label><label v-if="payment.method==='其他'" class="full">自定义方式<input v-model="payment.custom" placeholder="输入收支方式"/></label><label class="full">备注（可选）<input v-model="payment.note" placeholder="例如：尾款 / 元器件 / 快递费"/></label></div><footer class="dialog-footer"><button type="button" :disabled="busy" @click="payment=null">取消</button><button class="primary" :disabled="busy" type="submit">{{busy?'保存中…':`确认${entryKinds[payment.kind]}`}}</button></footer></form></section></div>
 <div v-if="remove" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="移入回收站"><div class="dialog-body"><h2>将项目移入回收站？</h2><p>{{remove.number}} · {{remove.title}}</p><p>项目将退出日常统计，已有收支和历史保留，之后可以恢复。</p><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button :disabled="busy" @click="remove=null">取消</button><button class="danger-button" :disabled="busy" @click="trash(remove!)">移入回收站</button></footer></section></div>
 <div v-if="voiding" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="作废流水"><form @submit.prevent="voidMoney"><div class="dialog-body"><h2>作废这笔{{entryKinds[voiding.kind]}}？</h2><p>{{money(voiding.amountCents)}} · {{orderNumber(voiding.orderId)}}</p><label>作废原因<input v-model="voidReason" placeholder="例如：金额填错，重新记录" required/></label><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button type="button" :disabled="busy" @click="voiding=null">取消</button><button class="danger-button" :disabled="busy" type="submit">确认作废</button></footer></form></section></div>
 <div v-if="copyText!==null" class="modal-layer upper" @mousedown.self="copyText=null"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="复制待收款"><div class="dialog-body"><h2>未结款清单</h2><p>同编号合计，一行一单，可直接发给对方核对。</p><textarea v-model="copyText" class="copy-preview" rows="10" aria-label="待收款清单"/><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button @click="copyText=null">关闭</button><button class="primary" :disabled="!copyText" @click="copy(copyText!)"><Icon name="copy"/>复制清单</button></footer></section></div>
 <div v-if="restoreName" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="恢复备份"><div class="dialog-body"><h2>恢复到这个备份版本？</h2><p class="directory">{{restoreName}}</p><p>当前订单、收支和历史将回到所选版本。程序会先另存一份当前数据的保护备份，之后仍可回溯。</p><div v-if="error" class="error-banner">{{error}}</div></div><footer class="dialog-footer"><button :disabled="busy" @click="restoreName=null">取消</button><button class="danger-button" :disabled="busy" @click="restoreBackup">{{busy?'正在恢复…':'备份当前数据并恢复'}}</button></footer></section></div>

 <div v-if="directoryDialog" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="数据目录"><form @submit.prevent="changeDirectory"><div class="dialog-body form-grid"><h2 class="full">{{directoryMode==='relocate'?'迁移数据目录':directoryMode==='open'?'打开已有账本':'选择新账本目录'}}</h2><p class="full">{{directoryMode==='relocate'?'先保护备份，再将当前账本复制到新目录。原目录保留。':directoryMode==='open'?'打开包含 workspace.json 和 ledger.db 的已有新版账本，不会自动创建空库。':'在所选目录创建一份新的独立账本。'}}</p><label class="full">目标文件夹<input v-model="directoryTarget" required placeholder="例如 D:\我的接单数据"/></label><button v-if="native" type="button" @click="pickFolder('directory')">浏览文件夹</button><div v-if="error" class="error-banner full">{{error}}</div></div><footer class="dialog-footer"><button type="button" :disabled="busy" @click="directoryDialog=false">取消</button><button class="primary" :disabled="busy" type="submit">{{busy?'处理中…':'确认'+(directoryMode==='relocate'?'迁移':directoryMode==='open'?'打开':'创建')}}</button></footer></form></section></div>
 <div v-if="exportDialog" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="导出表格"><form @submit.prevent="exportData"><div class="dialog-body form-grid"><h2 class="full">导出表格</h2><p class="full">导出为 Excel 可直接打开的 CSV，保留编号与金额，日期未知时留空。</p><label class="full">导出内容<select v-model="exportKind"><option value="orders">订单及收益汇总</option><option value="money">收支流水（含作废标识）</option><option value="tasks">任务与子任务</option><option value="unpaid">未结款明细</option></select></label><label class="check-label full"><input v-model="exportIncludeTrash" type="checkbox"/>包括回收站项目</label><div v-if="error" class="error-banner full">{{error}}</div></div><footer class="dialog-footer"><button type="button" :disabled="busy" @click="exportDialog=false">取消</button><button class="primary" :disabled="busy" type="submit">{{busy?'生成中…':'导出表格'}}</button></footer></form></section></div>
 <div v-if="discardDialog" class="modal-layer upper"><section class="dialog compact" role="dialog" aria-modal="true" aria-label="未保存修改"><div class="dialog-body"><h2>保留当前修改？</h2><p>项目有尚未保存的内容。继续编辑或保存后再关闭。</p></div><footer class="dialog-footer"><button @click="editor=null;discardDialog=false">放弃修改</button><button class="primary" @click="discardDialog=false">继续编辑</button></footer></section></div></template>
